import React from 'react';
import { ordersAPI } from '../services/api';

const Cart = ({ cart, setCart }) => {
  const updateQuantity = (id, newQuantity) => {
    if (newQuantity === 0) {
      setCart(cart.filter(item => item._id !== id));
    } else {
      setCart(cart.map(item => 
        item._id === id ? { ...item, quantity: newQuantity } : item
      ));
    }
  };

  const total = cart.reduce((sum, item) => sum + (item.price * item.quantity), 0);

  const handleCheckout = async () => {
    const address = prompt('Enter shipping address:');
    const phone = prompt('Enter phone number:');

    if (!address || !phone) {
      alert('Address and phone number are required!');
      return;
    }

    try {
      const orderData = {
        items: cart.map(item => ({
          product: item._id,
          quantity: item.quantity,
          price: item.price
        })),
        total,
        shippingAddress: address,
        phoneNumber: phone
      };

      await ordersAPI.create(orderData);
      setCart([]);
      alert('Order placed successfully!');
    } catch (error) {
      alert('Error placing order: ' + (error.response?.data?.message || 'Unknown error'));
    }
  };

  if (cart.length === 0) {
    return (
      <div className="container">
        <h2>Your Cart</h2>
        <p>Your cart is empty</p>
      </div>
    );
  }

  return (
    <div className="container">
      <h2>Your Cart</h2>
      {cart.map(item => (
        <div key={item._id} className="cart-item">
          <div>
            <h4>{item.name}</h4>
            <p className="price">₹{item.price}</p>
          </div>
          <div className="cart-controls">
            <button onClick={() => updateQuantity(item._id, item.quantity - 1)}>-</button>
            <span style={{ margin: '0 1rem', fontWeight: 'bold' }}>{item.quantity}</span>
            <button onClick={() => updateQuantity(item._id, item.quantity + 1)}>+</button>
          </div>
          <div>
            <strong className="price">₹{(item.price * item.quantity).toFixed(2)}</strong>
          </div>
        </div>
      ))}

      <div className="total-section">
        <h3>Total: ₹{total.toFixed(2)}</h3>
        <button onClick={handleCheckout} className="btn btn-success" style={{ marginTop: '1rem' }}>
          Proceed to Checkout
        </button>
      </div>
    </div>
  );
};

export default Cart;
